package com.gerenciadorrural.modules.organizations.application;
import com.gerenciadorrural.modules.identity.application.SynchronizeAuthenticatedUser; import com.gerenciadorrural.modules.organizations.domain.*; import com.gerenciadorrural.shared.security.application.CurrentUserProvider; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class ResolveTenantContext { private final CurrentUserProvider users; private final SynchronizeAuthenticatedUser synchronize; private final TenantContextResolverRepository repository; public ResolveTenantContext(CurrentUserProvider users,SynchronizeAuthenticatedUser synchronize,TenantContextResolverRepository repository){this.users=users;this.synchronize=synchronize;this.repository=repository;}
 @Transactional public Resolved execute(UUID organizationId,UUID farmId){var user=users.currentUser().orElseThrow(()->new IllegalStateException("A identidade autenticada não está disponível"));synchronize.execute(user);var resolved=repository.resolve(user.userId(),organizationId,farmId).orElseThrow(TenantContextNotAvailableException::new);return new Resolved(new TenantContext(new TenantId(resolved.organizationId()),user.userId(),resolved.farmId(),resolved.membershipId(),resolved.role(),resolved.farmScopeMode()),resolved.organizationName(),resolved.farmName());}
 public record Resolved(TenantContext context,String organizationName,String farmName){} }
